package review

import (
	"errors"
	"fmt"
	"net/http"

	"github.com/partio-io/cli/internal/github"
)

// Config is one gate run for one reviewed issue.
type Config struct {
	VerdictPath string
	Repo        string // owner/name
	Issue       int    // the reviewed issue
	Night       string // UTC date, YYYY-MM-DD, that names the night comment
	DryRun      bool   // record only; the only mode this gate supports yet
	APIBaseURL  string
	Token       string
	HTTPClient  *http.Client // nil means http.DefaultClient
}

// Result is what the gate found in the verdict file.
type Result struct {
	Valid   bool
	Outcome string // the verdict outcome when Valid
	Cause   string // why there is no verdict when not Valid
}

func (c Config) client() github.Client {
	return github.Client{BaseURL: c.APIBaseURL, Token: c.Token, HTTPClient: c.HTTPClient}
}

// Run loads the verdict for cfg.Issue and records it as one row in the
// tracking issue. A missing or invalid verdict is "no verdict": Run
// records that row with its cause and returns a Result that is not
// Valid, with a nil error. A non-nil error means the gate could not
// talk to GitHub. In dry-run mode Run reads the reviewed issue and
// changes nothing on it.
func Run(cfg Config) (Result, error) {
	if !cfg.DryRun {
		return Result{}, errors.New("only dry-run is supported")
	}
	gh := cfg.client()
	issue, err := gh.GetIssue(cfg.Repo, cfg.Issue)
	if err != nil {
		return Result{}, fmt.Errorf("read issue #%d: %w", cfg.Issue, err)
	}

	res := Result{}
	v, err := LoadVerdict(cfg.VerdictPath, cfg.Issue)
	var r string
	if err != nil {
		res.Cause = err.Error()
		r = noVerdictRow(issue, res.Cause)
	} else {
		res.Valid, res.Outcome = true, v.Outcome
		r = row(issue, v, cfg.DryRun)
	}

	tracking, err := findOrCreateTracking(gh, cfg.Repo)
	if err != nil {
		return Result{}, err
	}
	if err := appendRow(gh, cfg.Repo, tracking, cfg.Night, r); err != nil {
		return Result{}, err
	}
	return res, nil
}
package review

import (
	"fmt"
	"strings"

	"github.com/partio-io/cli/internal/github"
)

// row is one tracking line for a valid verdict: number, title, verdict,
// reason and link. A rewrite carries its full proposed text in a
// collapsed section, indented so it stays under its row, with the body
// fenced so its own markup cannot close the section or hide later rows.
func row(issue github.Issue, v Verdict, dryRun bool) string {
	verdict := "**" + v.Outcome + "**"
	if dryRun {
		verdict += " (dry run)"
	}
	line := fmt.Sprintf("- #%d · %s · %s · %s · [link](%s)\n",
		issue.Number, oneLine(issue.Title), verdict, reason(v), issue.HTMLURL)
	if v.Outcome != OutcomeRewrite {
		return line
	}
	return line + indent(rewriteDetails(*v.Rewrite))
}

// noVerdictRow is the tracking line for a missing or invalid verdict.
func noVerdictRow(issue github.Issue, cause string) string {
	return fmt.Sprintf("- #%d · %s · **no verdict** · %s · [link](%s)\n",
		issue.Number, oneLine(issue.Title), oneLine(cause), issue.HTMLURL)
}

func reason(v Verdict) string {
	switch {
	case v.Outcome == OutcomeClose && v.CloseReason == ReasonDuplicate:
		return fmt.Sprintf("duplicate of #%d", v.DuplicateOf)
	case v.Outcome == OutcomeClose:
		return v.CloseReason
	case v.Outcome == OutcomeRewrite && len(v.Rewrite.Changes) > 0:
		return oneLine(strings.Join(v.Rewrite.Changes, "; "))
	}
	return oneLine(v.Fit.Reason)
}

func rewriteDetails(rw Rewrite) string {
	var b strings.Builder
	b.WriteString("\n<details><summary>Proposed rewrite</summary>\n\n")
	fmt.Fprintf(&b, "**Title:** %s\n\n", oneLine(rw.Title))
	fence := fenceFor(rw.Body)
	b.WriteString(fence + "markdown\n")
	b.WriteString(strings.TrimRight(rw.Body, "\n"))
	b.WriteString("\n" + fence + "\n\n</details>\n\n")
	return b.String()
}

// fenceFor returns a backtick fence longer than any backtick run in
// text, so text cannot close it.
func fenceFor(text string) string {
	longest, run := 0, 0
	for _, r := range text {
		if r == '`' {
			run++
			longest = max(longest, run)
		} else {
			run = 0
		}
	}
	return strings.Repeat("`", max(3, longest+1))
}

// indent nests text under a list item, so lines that start with "- "
// in a rewrite body never read as rows of their own.
func indent(text string) string {
	lines := strings.Split(text, "\n")
	for i, l := range lines {
		if l != "" {
			lines[i] = "  " + l
		}
	}
	return strings.Join(lines, "\n")
}

func oneLine(s string) string {
	return strings.Join(strings.Fields(s), " ")
}
package github

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
)

// Issue is the part of a GitHub issue the minion tools read.
type Issue struct {
	Number  int    `json:"number"`
	Title   string `json:"title"`
	Body    string `json:"body"`
	HTMLURL string `json:"html_url"`
	// PullRequest is set when the item is a pull request: the issues
	// API lists pull requests as issues.
	PullRequest *struct{} `json:"pull_request,omitempty"`
}

// GetIssue reads issue number in repo.
func (c Client) GetIssue(repo string, number int) (Issue, error) {
	req, err := http.NewRequest(http.MethodGet,
		fmt.Sprintf("%s/repos/%s/issues/%d", c.BaseURL, repo, number), nil)
	if err != nil {
		return Issue{}, fmt.Errorf("get issue: %w", err)
	}
	var issue Issue
	if err := c.Do(req, &issue); err != nil {
		return Issue{}, fmt.Errorf("get issue: %w", err)
	}
	return issue, nil
}

// OpenIssuesWithLabel lists every open issue in repo that carries
// label, following pagination. It leaves out pull requests, which the
// issues API also returns.
func (c Client) OpenIssuesWithLabel(repo, label string) ([]Issue, error) {
	var all []Issue
	path := fmt.Sprintf("/repos/%s/issues?state=open&labels=%s", repo, url.QueryEscape(label))
	err := GetPages(c, path, 0, func(page []Issue) bool {
		for _, is := range page {
			if is.PullRequest == nil {
				all = append(all, is)
			}
		}
		return true
	})
	if err != nil {
		return nil, fmt.Errorf("list issues: %w", err)
	}
	return all, nil
}

// CreateIssue opens a new issue in repo with the given labels.
func (c Client) CreateIssue(repo, title, body string, labels []string) (Issue, error) {
	payload, err := json.Marshal(map[string]any{"title": title, "body": body, "labels": labels})
	if err != nil {
		return Issue{}, fmt.Errorf("encode issue: %w", err)
	}
	req, err := http.NewRequest(http.MethodPost,
		fmt.Sprintf("%s/repos/%s/issues", c.BaseURL, repo), bytes.NewReader(payload))
	if err != nil {
		return Issue{}, fmt.Errorf("create issue: %w", err)
	}
	var issue Issue
	if err := c.Do(req, &issue); err != nil {
		return Issue{}, fmt.Errorf("create issue: %w", err)
	}
	return issue, nil
}
package github

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"net/url"
)

// EnsureLabel creates label name in repo when it is absent and leaves
// an existing label as it is.
func (c Client) EnsureLabel(repo, name, color, description string) error {
	req, err := http.NewRequest(http.MethodGet,
		fmt.Sprintf("%s/repos/%s/labels/%s", c.BaseURL, repo, url.PathEscape(name)), nil)
	if err != nil {
		return fmt.Errorf("get label: %w", err)
	}
	err = c.Do(req, nil)
	var status *StatusError
	switch {
	case err == nil:
		return nil
	case !errors.As(err, &status) || status.Code != http.StatusNotFound:
		return fmt.Errorf("get label: %w", err)
	}

	payload, err := json.Marshal(map[string]string{"name": name, "color": color, "description": description})
	if err != nil {
		return fmt.Errorf("encode label: %w", err)
	}
	req, err = http.NewRequest(http.MethodPost,
		fmt.Sprintf("%s/repos/%s/labels", c.BaseURL, repo), bytes.NewReader(payload))
	if err != nil {
		return fmt.Errorf("create label: %w", err)
	}
	if err := c.Do(req, nil); err != nil {
		return fmt.Errorf("create label: %w", err)
	}
	return nil
}
// Package github is the GitHub REST client the minion tools share.
package github

import (
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
)

// Client holds what every GitHub request needs.
type Client struct {
	BaseURL    string       // GitHub API root, e.g. https://api.github.com
	Token      string       // sent as a bearer token
	HTTPClient *http.Client // nil means http.DefaultClient
}

// StatusError is the error Do returns for a non-2xx response. Callers
// that must tell "absent" from "broken" check Code with errors.As.
type StatusError struct {
	Method string
	Path   string
	Code   int
	Status string
	Detail []byte // up to 512 bytes of the response body
}

func (e *StatusError) Error() string {
	return fmt.Sprintf("github: %s %s: %s: %s", e.Method, e.Path, e.Status, e.Detail)
}

// Do executes one GitHub API request and decodes the response into out
// when out is non-nil. A non-2xx response is a *StatusError that names
// the method, the path, the status and up to 512 bytes of the body.
func (c Client) Do(req *http.Request, out any) error {
	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("Authorization", "Bearer "+c.Token)
	client := c.HTTPClient
	if client == nil {
		client = http.DefaultClient
	}
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer func() {
		// Drain what is left so the connection can be reused.
		if _, drainErr := io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10)); drainErr != nil {
			slog.Debug("draining response body", "url", req.URL.Path, "error", drainErr)
		}
		if closeErr := resp.Body.Close(); closeErr != nil {
			slog.Debug("closing response body", "url", req.URL.Path, "error", closeErr)
		}
	}()
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		detail, readErr := io.ReadAll(io.LimitReader(resp.Body, 512))
		if readErr != nil {
			detail = fmt.Appendf(nil, "(error body unreadable: %v)", readErr)
		}
		return &StatusError{Method: req.Method, Path: req.URL.Path, Code: resp.StatusCode, Status: resp.Status, Detail: detail}
	}
	if out == nil {
		return nil
	}
	return json.NewDecoder(resp.Body).Decode(out)
}

