func closeVerdictFor(reason string) string {
	claims, premise := `[]`, "no-claims"
	switch reason {
	case ReasonFalsePremise:
		claims, premise = `[{"claim": "push has no retry", "evidence": "internal/hooks/prepush.go", "verdict": "fails", "excerpt": "retry(push)"}]`, "fails"
	case ReasonCouldNotVerify:
		claims, premise = `[{"claim": "pushes fail often", "evidence": "no logs in the repo", "verdict": "unresolved", "excerpt": ""}]`, "unresolved"
	}
	fit := `{"applies": true, "reason": "in scope"}`
	if reason == ReasonDoesNotApply {
		fit = `{"applies": false, "reason": "partio has no server"}`
	}
