62	// closeVerdictFor is a valid close verdict for issue 12 with reason.
63	func closeVerdictFor(reason string) string {
64		claims, premise := `[]`, "no-claims"
65		switch reason {
66		case ReasonFalsePremise:
67			claims, premise = `[{"claim": "push has no retry", "evidence": "internal/hooks/prepush.go", "verdict": "fails", "excerpt": "retry(push)"}]`, "fails"
68		case ReasonCouldNotVerify:
69			claims, premise = `[{"claim": "pushes fail often", "evidence": "no logs in the repo", "verdict": "unresolved", "excerpt": ""}]`, "unresolved"
70		}
71		fit := `{"applies": true, "reason": "in scope"}`
72		if reason == ReasonDoesNotApply {
73			fit = `{"applies": false, "reason": "partio has no server"}`
74		}
75		built := `{"built": false, "evidence": ""}`
76		if reason == ReasonBuilt {
77			built = `{"built": true, "evidence": "internal/hooks/retry.go already retries"}`
78		}
79		dupOf, dupes := "", `[]`
80		if reason == ReasonDuplicate {
81			dupOf, dupes = `"duplicate_of": 13,`, `[{"issue": 13, "same": true, "why": "same retry idea"}]`
82		}
83		return `{"issue": 12, "outcome": "close", "close_reason": "` + reason + `", ` + dupOf +
84			`"premise": {"verdict": "` + premise + `", "claims": ` + claims + `},` +
85			`"fit": ` + fit + `, "built": ` + built + `, "duplicates": ` + dupes + `}`
86	}
87	
88	// A close posts the evidence comment, adds minion-reviewed and closes
89	// the issue: completed for built, not_planned for every other reason.
90	// A duplicate close reads the issue that stays, to name and link it.
91	func TestGateCloseActsOnTheIssue(t *testing.T) {
92		tests := []struct {
93			reason      string
94			stateReason string
95		}{
96			{ReasonBuilt, "completed"},
97			{ReasonFalsePremise, "not_planned"},
98			{ReasonDoesNotApply, "not_planned"},
99			{ReasonDuplicate, "not_planned"},
100			{ReasonCouldNotVerify, "not_planned"},
101		}
102		for _, tt := range tests {
103			t.Run(tt.reason, func(t *testing.T) {
104				gh := newFakeGitHub()
105				gh.labels = append(gh.labels, ReviewedLabel)
106				gh.issues[12] = issueJSON(12, "Add a retry to the pre-push hook", "body",
107					[]string{"minion-proposal", "minion-approved"})
108				gh.trackingIssue(77)
109	
110				res := runAct(t, gh, 12, writeVerdict(t, closeVerdictFor(tt.reason)))
111	
112				if !res.Valid || res.Outcome != OutcomeClose {
113					t.Fatalf("Result = %+v, want a valid close", res)
114				}
115				want := []string{
116					"GET /repos/partio-io/cli/issues/12",
117					"GET /repos/partio-io/cli/pulls",
118				}
119				if tt.reason == ReasonDuplicate {
120					want = append(want, "GET /repos/partio-io/cli/issues/13")
121				}
122				want = append(want,
123					"GET /repos/partio-io/cli/labels/minion-reviewed",
124					"POST /repos/partio-io/cli/issues/12/comments",
125					"POST /repos/partio-io/cli/issues/12/labels",
126					"PATCH /repos/partio-io/cli/issues/12",
127					"GET /repos/partio-io/cli/issues",
128					"GET /repos/partio-io/cli/issues/77/comments",
129					"POST /repos/partio-io/cli/issues/77/comments",
130				)
131				if !slices.Equal(gh.requests, want) {
132					t.Fatalf("requests:\n%s\nwant:\n%s", strings.Join(gh.requests, "\n"), strings.Join(want, "\n"))
133				}
134				issue := gh.issues[12]
135				if issue["state"] != "closed" || issue["state_reason"] != tt.stateReason {
136					t.Errorf("state = %v/%v, want closed/%s", issue["state"], issue["state_reason"], tt.stateReason)
137				}
138				if !slices.Contains(labelNames(issue), ReviewedLabel) {
139					t.Errorf("labels = %q, want %s", labelNames(issue), ReviewedLabel)
140				}
141				if got := len(gh.comments[12]); got != 1 {
142					t.Fatalf("reviewed issue has %d comments, want 1", got)
143				}
144				body := gh.comments[12][0]["body"].(string)
145				if tt.reason == ReasonDuplicate {
146					link := "[Cache the session index](https://github.com/partio-io/cli/issues/13)"
147					if !strings.Contains(body, "#13") || !strings.Contains(body, link) {
148						t.Errorf("duplicate comment does not name and link #13:\n%s", body)
149					}
150				}
151			})
152		}
153	}

