name: Proposal Review

# Reviews proposal issues one at a time. Each issue gets a fresh review
# session, and the review gate records its verdict in the tracking
# issue. A dry run changes nothing on the reviewed issues, so a closed
# issue is a valid input: use one with a known answer to test the
# review.

on:
  workflow_dispatch:
    inputs:
      issues:
        description: "Issue numbers to review, separated by spaces or commas (e.g., 30 31)"
        required: true
        type: string
      dry_run:
        description: "Record each verdict in the tracking issue only (only true works in this version)"
        required: false
        default: true
        type: boolean

# Two dispatches at once would both edit the night comment of the
# tracking issue, and one would overwrite the rows of the other.
concurrency:
  group: proposal-review
  cancel-in-progress: false

jobs:
  review:
    runs-on: github-runner-partio-minion-ai-01
    timeout-minutes: 240
    steps:
      - name: Checkout
        uses: actions/checkout@v4

      - name: Install minions
        run: |
          go install github.com/partio-io/minions/cmd/minions@v0.0.14
          echo "$(go env GOPATH)/bin" >> "$GITHUB_PATH"

      # One session per issue, in sequence. A crashed session or a "no
      # verdict" exit from the gate does not stop the loop: the gate
      # records a "no verdict" row for that issue, and the next issue
      # gets its own review. The job fails at the end if any gate
      # failed, so the run shows it.
      - name: Review issues
        env:
          GH_TOKEN: ${{ secrets.GH_PAT }}
          ISSUES: ${{ inputs.issues }}
          DRY_RUN: ${{ inputs.dry_run }}
          # The review session runs in an isolated minions worktree, so
          # the verdict must be written to an absolute path in this
          # workspace for the gate to find it.
          MINION_REVIEW_DIR: ${{ github.workspace }}/.minion-review
        run: |
          if [ "$DRY_RUN" != "true" ]; then
            echo "::error::Only a dry run is available in this version."
            exit 2
          fi

          LIST=$(printf '%s' "$ISSUES" | tr ',#' '  ')
          # A leading zero is refused: the gate parses "010" as octal 8,
          # so it would check the verdict of #10 against #8.
          for ISSUE in $LIST; do
            case "$ISSUE" in
              ''|0*|*[!0-9]*)
                echo "::error::Not an issue number: $ISSUE"
                exit 2
                ;;
            esac
          done
          if [ -z "$LIST" ]; then
            echo "::error::The issue list is empty."
            exit 2
          fi

          # One night per run, so every row of this run lands in one
          # tracking comment even if the run crosses midnight UTC.
          NIGHT=$(date -u +%F)
          FAILED=""
          for ISSUE in $LIST; do
            echo "::group::Review #$ISSUE"
            rm -rf "$MINION_REVIEW_DIR"
            mkdir -p "$MINION_REVIEW_DIR"
            if ! minions run .minions/programs/review.md --issue "$ISSUE"; then
              echo "::warning::The review session for #$ISSUE failed. The gate records what it left."
            fi
            if ! go run ./cmd/minion-review gate \
              --issue "$ISSUE" \
              --verdict "$MINION_REVIEW_DIR/verdict.json" \
              --dry-run \
              --night "$NIGHT"; then
              FAILED="$FAILED #$ISSUE"
            fi
            echo "::endgroup::"
          done

          if [ -n "$FAILED" ]; then
            echo "::error::The gate failed for:$FAILED"
            exit 1
	if end < 0 {
